t.script:
(function(){function ev_isXO(msg){msg=msg||"";return msg.indexOf("cross-origin frame")>-1||msg.indexOf("named property 'href'")>-1||msg.indexOf("Blocked a frame")>-1;}
        window.addEventListener("error",function(e){if(ev_isXO(e&&e.message)){if(e.stopImmediatePropagation){e.stopImmediatePropagation();}if(e.preventDefault){e.preventDefault();}return false;}},true);
        window.addEventListener("unhandledrejection",function(e){var r=e&&e.reason;var m=(r&&r.message)?r.message:(""+r);if(ev_isXO(m)){if(e.stopImmediatePropagation){e.stopImmediatePropagation();}if(e.preventDefault){e.preventDefault();}return false;}},true);})();

/* potlačí neškodnou Odoo chybu SecurityError při čtení cross-origin iframu */
window.addEventListener('error', function (e) {
    var m = (e && e.message) ? e.message : '';
    if (m.indexOf('cross-origin frame') > -1 || m.indexOf("named property 'href'") > -1) {
        if (e.stopImmediatePropagation) { e.stopImmediatePropagation(); }
        if (e.preventDefault) { e.preventDefault(); }
        return false;
    }
}, true);

/* zavřít popup po kliknutí na odkaz uvnitř */
document.addEventListener('click', function (e) {
    var link = e.target.closest('details a');
    if (!link) return;
    var d = link.closest('details');
    if (d) d.open = false;
});

/* horní lišta: schovat při scrollu dolů, ukázat při scrollu nahoru */
(function () {
    var ua = navigator.userAgent || '';
    if (/Instagram|FBAN|FBAV|FB_IAB|Messenger|MicroMessenger|Snapchat|Pinterest/i.test(ua)) { return; }
    var nav = document.querySelector('.ev-topbar');
    if (!nav) { return; }
    var lastY = window.pageYOffset || 0;
    var ticking = false;
    function closeMenus() {
        var open = nav.querySelectorAll('details[open]');
        for (var i = 0; i < open.length; i++) { open[i].open = false; }
    }
    function navScroll() {
        var y = window.pageYOffset || 0;
        if (y > lastY + 4) {
            if (y > 90) { nav.classList.add('ev-nav-hidden'); closeMenus(); }
            lastY = y;
        } else if (lastY - 4 > y) {
            nav.classList.remove('ev-nav-hidden');
            lastY = y;
        }
        ticking = false;
    }
    window.addEventListener('scroll', function () {
        if (ticking === false) { ticking = true; window.requestAnimationFrame(navScroll); }
    }, { passive: true });
})();
